      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators and the quantum spin Hall effect established a new class of quantum matter, joining deep conceptual advances to robust experimental signatures.",
        "attribution": "Kane and Mele supplied central theoretical predictions; Molenkamp's experiments demonstrated the quantum spin Hall state. The broader experimental discovery of three-dimensional topological insulators also involved Hasan, making any three-person allocation selective.",
        "maturity": "The theory and defining effects have been tested across many materials and transport measurements over more than a decade.",
        "uncertainties": [
          "The candidate groups several related milestones, and the relative credit for the quantum spin Hall and three-dimensional topological-insulator discoveries is not captured cleanly by one trio."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B059",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Tunneling magnetoresistance made spin-dependent transport in magnetic tunnel junctions both a major physical effect and a practical basis for dense magnetic storage.",
        "attribution": "Moodera and Miyazaki independently established room-temperature tunnel magnetoresistance, while Parkin made major contributions to giant magnetoresistance and its applications. Their achievements are related but not identical.",
        "maturity": "The effects are thoroughly established and underpin widely deployed technologies.",
        "uncertainties": [
          "The candidate combines room-temperature tunneling magnetoresistance with giant magnetoresistance, whose experimental histories and credit differ."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B033",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory gave condensed-matter physics a powerful framework for understanding local correlations and the metal-insulator transition in strongly interacting electrons.",
        "attribution": "Georges, Vollhardt, and Kotliar were central to establishing and developing the method and its applications.",
        "maturity": "The framework has been independently implemented, extended, and applied to a wide range of materials for decades.",
        "uncertainties": [
          "The method has a broader history of development, and a prize would need to distinguish its foundational formulation from subsequent extensions."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase revealed that quantum phases can have observable consequences beyond local forces, with lasting influence across physics.",
        "attribution": "Aharonov's work established the electromagnetic phase effect, while Berry identified geometric phase in adiabatic evolution. The paired recognition is compelling but covers distinct contributions.",
        "maturity": "Both effects have extensive experimental confirmation and are now standard concepts in quantum and condensed-matter physics.",
        "uncertainties": [
          "The candidate bundles two related but historically distinct discoveries, so their scope and relative weight would need careful definition."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Hideo Hosono",
        "Yoichi Kamihara"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of iron-based high-temperature superconductors opened a major new family of superconductors and reshaped research into unconventional pairing.",
        "attribution": "Kamihara's discovery with Hosono's leadership and materials program provides a clear central attribution.",
        "maturity": "The superconducting family has been studied extensively since its discovery, with established phase diagrams and multiple materials.",
        "uncertainties": [
          "The microscopic pairing mechanism remains unsettled, and the lasting importance of this family relative to other unconventional superconductors is still being assessed."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Chang C. Tsuei",
        "Dale J. Van Harlingen",
        "John R. Kirtley"
      ],
      "assessment": {
        "nobel_worthiness": "Phase-sensitive experiments established d-wave pairing in cuprates, resolving a central question about the order parameter in high-temperature superconductivity.",
        "attribution": "Tsuei and Kirtley led landmark phase-sensitive tests, while Van Harlingen made important earlier contributions to Josephson-junction measurements of the pairing symmetry.",
        "maturity": "The evidence has been replicated through multiple phase-sensitive methods and remains foundational to the field.",
        "uncertainties": [
          "The candidate groups a sequence of complementary experiments, so the boundary between decisive demonstration and prior enabling work is not sharp."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Bruce E. Kane",
        "Daniel Loss",
        "Lieven M. K. Vandersypen"
      ],
      "assessment": {
        "nobel_worthiness": "Semiconductor spin qubits connected quantum information to established materials platforms and helped make controllable solid-state quantum systems experimentally accessible.",
        "attribution": "Kane and Loss provided influential proposals for donor and quantum-dot spin qubits; Vandersypen helped demonstrate and control electron spins in quantum dots.",
        "maturity": "Spin control and coherent operations are well established, though scaling to fault-tolerant systems remains an active challenge.",
        "uncertainties": [
          "The candidate spans distinct qubit architectures and many experimental advances, so credit for the overall field is diffuse."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Mehran Kardar",
        "Yi-Cheng Zhang",
        "Kazumasa A. Takeuchi"
      ],
      "assessment": {
        "nobel_worthiness": "Kardar-Parisi-Zhang universality is a far-reaching theory of growing interfaces, and its experimental confirmation gave strong evidence that a shared scaling description applies to real systems.",
        "attribution": "Kardar and Zhang developed the central theoretical framework with Giorgio Parisi; Takeuchi's experiments provided especially clear confirmation. The supplied names omit Parisi, which complicates attribution.",
        "maturity": "The theory is decades old, and the predicted scaling behavior has been confirmed in multiple experimental settings.",
        "uncertainties": [
          "The credited names do not include all central contributors to the original theory, and experimental confirmation was a collective effort."
        ]
      }
    }
  ]
